def _handle_dict(target, spec, scope):
    if not isinstance(target, dict):
        raise MatchError("{0!r} is not a dict, expected dict for spec {1!r}", target, spec)

    ret = {}
    spec_keys = sorted(spec.keys(), key=_precedence)
    target_keys = set(target.keys())
    matched_target_keys = set()

    for spec_key in spec_keys:
        spec_val = spec[spec_key]
        is_required = type(spec_key) is Required
        is_optional = type(spec_key) is Optional

        if is_required:
            match_key = spec_key.key
        elif is_optional:
            match_key = spec_key.key
        else:
            match_key = spec_key

        matched_any = False
        for target_key in target_keys:
            if target_key in matched_target_keys:
                continue

            try:
                scope[glom](target_key, match_key, scope)
            except GlomError:
                continue

            matched_target_keys.add(target_key)
            matched_any = True
            target_val = target[target_key]
            ret[target_key] = scope[glom](target_val, spec_val, chain_child(scope))

        if not matched_any and is_required:
            raise MatchError("target missing expected keys {0!r}", spec_key)

    unmatched_keys = target_keys - matched_target_keys
    if unmatched_keys:
        raise MatchError("target has unexpected keys {0!r}", unmatched_keys)

    return ret


def _glom_match(target, spec, scope):
    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(target, spec)
        return target

    if isinstance(spec, dict):
        return _handle_dict(target, spec, scope)

    if isinstance(spec, (list, tuple)):
        if type(spec) is tuple:
            if type(target) is not tuple:
                raise MatchError("{0!r} is not a tuple, expected tuple for spec {1!r}", target, spec)
            if len(target) != len(spec):
                raise MatchError("target tuple length {0} != spec tuple length {1}", len(target), len(spec))
            ret = []
            for target_item, spec_item in zip(target, spec):
                ret.append(scope[glom](target_item, spec_item, chain_child(scope)))
            return tuple(ret)
        else:
            if not isinstance(target, list):
                raise MatchError("{0!r} is not a list, expected list for spec {1!r}", target, spec)
            if len(spec) != 1:
                raise MatchError("list spec must have exactly one element, got {0}", len(spec))
            ret = []
            for target_item in target:
                ret.append(scope[glom](target_item, spec[0], chain_child(scope)))
            return ret

    if isinstance(spec, set):
        if not isinstance(target, set):
            raise MatchError("{0!r} is not a set, expected set for spec {1!r}", target, spec)
        if len(spec) != 1:
            raise MatchError("set spec must have exactly one element, got {0}", len(spec))
        spec_item = next(iter(spec))
        for target_item in target:
            scope[glom](target_item, spec_item, chain_child(scope))
        return target

    if isinstance(spec, frozenset):
        if not isinstance(target, frozenset):
            raise MatchError("{0!r} is not a frozenset, expected frozenset for spec {1!r}", target, spec)
        if len(spec) != 1:
            raise MatchError("frozenset spec must have exactly one element, got {0}", len(spec))
        spec_item = next(iter(spec))
        for target_item in target:
            scope[glom](target_item, spec_item, chain_child(scope))
        return target

    if callable(spec):
        try:
            result = spec(target)
            if not result:
                raise MatchError("{0!r} is not truthy", result)
        except Exception:
            raise MatchError("{0!r} does not match {1!r}", target, spec)
        return target

    if target == spec:
        return target

    raise MatchError("{0!r} does not match {1!r}", target, spec)
